SELECT monthly_fee_bucket, min_monthly_fee FROM (SELECT CASE WHEN monthly_fee >= 196 THEN 'high' WHEN monthly_fee >= 41 THEN 'mid' ELSE 'low' END AS monthly_fee_bucket, MIN(monthly_fee) AS min_monthly_fee FROM subscriptions GROUP BY CASE WHEN monthly_fee >= 196 THEN 'high' WHEN monthly_fee >= 41 THEN 'mid' ELSE 'low' END) AS agg WHERE min_monthly_fee >= 190 ORDER BY monthly_fee_bucket LIMIT 3;
